RECIPE = {"lr": 2e-3, "n_envs": 128, "rollout_len": 16, "n_minibatches": 8, "ppo_epochs": 2, "ent_coef": 0.01, "gamma": 0.99, "gae_lambda": 0.85}
LAYOUTS = [(0, 0, 0), (1, 0, 0), (0, 1, 0), (0, 0, 1)]
TYPE_MINOR = False
OBS_SYM = True
USE_LN = True
GLOB_CTX = True
DILATED = True
DENSE_REMAP = False
SEP_CRITIC = True
STEM = 64
WIDTH = 40
HEAD = 32
GLOB = 64
MASK_EMB = 8
DENSE_EMB = 4
DENSE_OUT = 4
CRIT = 32


def lay(t, tr, fy, fx):
    if tr:
        t = t.transpose(-1, -2)
    if fy:
        t = t.flip(-2)
    if fx:
        t = t.flip(-1)
    return t


def unlay(t, tr, fy, fx):
    if fx:
        t = t.flip(-1)
    if fy:
        t = t.flip(-2)
    if tr:
        t = t.transpose(-1, -2)
    return t


class ChanLN(nn.Module):
    def __init__(self, c):
        super().__init__()
        self.ln = nn.LayerNorm(c)

    def forward(self, x):
        return self.ln(x.permute(0, 2, 3, 1)).permute(0, 3, 1, 2)


def norm(c):
    if USE_LN:
        return ChanLN(c)
    return nn.Identity()


class ResBlock(nn.Module):
    def __init__(self, c, dil):
        super().__init__()
        self.conv = nn.Conv2d(c, c, 3, padding=dil, dilation=dil)
        self.norm = norm(c)
        self.use_ctx = GLOB_CTX
        if GLOB_CTX:
            self.ctx = nn.Linear(2 * c, c)

    def forward(self, x):
        y = x + self.conv(x)
        if self.use_ctx:
            g = self.ctx(torch.cat([x.mean((2, 3)), x.amax((2, 3))], dim=1))
            y = y + g[:, :, None, None]
        return F.relu(self.norm(y))


class Critic(nn.Module):
    def __init__(self, cin):
        super().__init__()
        self.c1 = nn.Conv2d(cin, CRIT, 1)
        self.n1 = ChanLN(CRIT)
        self.c2 = nn.Conv2d(CRIT, CRIT, 3, stride=2, padding=1)
        self.fc1 = nn.Linear(2 * CRIT, 64)
        self.fc2 = nn.Linear(64, 1)

    def forward(self, o):
        h = F.relu(self.n1(self.c1(o)))
        h = F.relu(self.c2(h))
        h = F.relu(self.fc1(torch.cat([h.mean((2, 3)), h.amax((2, 3))], dim=1)))
        return self.fc2(h).squeeze(1)


class Net(nn.Module):
    def __init__(self, spec):
        super().__init__()
        self.Y = int(spec.Y)
        self.X = int(spec.X)
        self.n_place = int(spec.n_place)
