        cells = self.Y * self.X
        square = self.Y == self.X
        lays = [l for l in LAYOUTS if square or not l[0]]
        if len(lays) == 0:
            lays = [(0, 0, 0)]
        self.layouts = lays
        self.grid = (self.n_place % cells == 0)
        if OBS_SYM:
            syms = [(t, a, b) for t in (0, 1) for a in (0, 1) for b in (0, 1)]
            self.syms = [s for s in syms if square or not s[0]]
        else:
            self.syms = [(0, 0, 0)]
