            mask_in = self.K * len(self.layouts)
        else:
            self.K = 1
            self.mask_embed = nn.Linear(self.n_place, cells * MASK_EMB)
            mask_in = MASK_EMB
        if DENSE_REMAP:
            self.dense_in = nn.Linear(self.n_actions, cells * DENSE_EMB)
            mask_in += DENSE_EMB
        if USE_LN:
