        mfull = mask.to(obs.dtype)
        if DONE_FIRST:
            mp = mfull[:, 1:1 + self.n_place]
        else:
            mp = mfull[:, :self.n_place]
        if self.grid:
            mi = mp.reshape(B, K, Y, X)
        else:
