        self.grid = (self.n_place % cells == 0)
        if self.grid:
            self.K = self.n_place // cells
            n_mb = 2 if MASK_MINOR else 1
            n_ms = len(self.syms) if MASK_SYM else 1
            mask_in = self.K * n_mb * n_ms
        else:
            self.K = 1
            self.mask_embed = nn.Linear(self.n_place, cells * MASK_EMB)
